CREATE OR REPLACE FUNCTION public.protect_membership_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF auth.role() = 'authenticated' AND NOT public.has_role(auth.uid(), 'admin') THEN IF TG_OP = 'INSERT' THEN IF COALESCE(NEW.custom_billing, false) OR NOT EXISTS (SELECT 1 FROM public.pricing_config WHERE tier = NEW.membership_tier AND is_default) THEN RAISE EXCEPTION 'Membership assignment requires admin access'; END IF; ELSIF NEW.membership_tier IS DISTINCT FROM OLD.membership_tier OR NEW.custom_billing IS DISTINCT FROM OLD.custom_billing THEN RAISE EXCEPTION 'Membership assignment requires admin access'; END IF; END IF; RETURN NEW; END; $$; CREATE TRIGGER protect_membership_assignment BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_membership_assignment();